fn stop(mut self) {
    if let Some(stop_tx) = self.stop_tx.take() {
        let _ = stop_tx.send(());
    }
    if let Some(join_handle) = self.join_handle.take() {
        // Detach with a bounded join: the monitor thread blocks on a nested
        // tokio runtime running `tokio::signal::ctrl_c()`. In non-interactive
        // / no-TTY contexts that future can fail to wake even after the stop
        // signal is sent, so an unconditional `join()` here deadlocks the
        // whole process after the model response has already arrived. We give
        // the thread a brief window to exit cleanly, then detach so the CLI
        // can finish instead of hanging forever.
        let (done_tx, done_rx) = mpsc::channel();
        thread::spawn(move || {
            let _ = join_handle.join();
            let _ = done_tx.send(());
        });
        let _ = done_rx.recv_timeout(std::time::Duration::from_millis(500));
    }
}

