pub async fn next_event(&mut self) -> Result<Option<StreamEvent>, ApiError> {
    loop {
        if let Some(event) = self.pending.pop_front() {
            self.observe_event(&event);
            // `message_stop` is the terminal event of an Anthropic SSE
            // stream. Some OpenAI-compatible gateways keep the HTTP
            // connection alive after sending it instead of closing the body,
            // so a subsequent `chunk().await` would block forever waiting for
            // bytes that never arrive. Mark the stream done as soon as we hand
            // out `message_stop` so the next `next_event()` returns `None`
            // immediately instead of deadlocking.
            if matches!(event, StreamEvent::MessageStop(_)) {
                self.done = true;
            }
            return Ok(Some(event));
        }

        if self.done {
            let remaining = self.parser.finish()?;
            self.pending.extend(remaining);
            if let Some(event) = self.pending.pop_front() {
                return Ok(Some(event));
            }
            return Ok(None);
        }

