pub fn build_http_client_with(config: &ProxyConfig) -> Result<reqwest::Client, ApiError> {
    let mut builder = reqwest::Client::builder()
        .no_proxy()
        // The CLI builds this client outside of any Tokio runtime and later
        // drives requests via a freshly-created `Runtime::block_on`. hyper's
        // idle-connection pool can cache a connection bound to a reactor that is
        // no longer driving IO, which makes a subsequent streaming request hang
        // forever (the response bytes arrive at the OS socket but the future is
        // never woken). Disabling idle pooling forces every request to open a
        // fresh connection on the currently-active runtime, eliminating the
        // cross-runtime reactor mismatch that otherwise deadlocks streaming.
        .pool_max_idle_per_host(0)
        .user_agent("clawd-rust-tools/0.1");

