    let resolved_model = api::resolve_model_alias(&model);
    // Build the dedicated runtime FIRST, then construct the reqwest-backed
    // provider client while inside this runtime's context (`_enter`). reqwest
    // binds its connection pool / IO to whatever reactor is active at client
    // construction time; if the client is built with no runtime active (as
    // happened previously) the later `runtime.block_on(...)` drives a future
    // whose socket wakeups are registered on a different/!dead reactor, so the
    // response bytes arrive at the OS socket but the future is never woken —
    // a hard hang. Constructing the client inside `runtime.enter()` guarantees
    // the connection pool is bound to the very runtime that will drive it.
    let runtime = tokio::runtime::Runtime::new()?;
    let client = {
        let _enter = runtime.enter();
        match detect_provider_kind(&resolved_model) {
            ProviderKind::Anthropic => {
                let auth = resolve_cli_auth_source()?;
                let inner = AnthropicClient::from_auth(auth)
                    .with_base_url(api::read_base_url())
                    .with_prompt_cache(PromptCache::new(session_id));
                ApiProviderClient::Anthropic(inner)
            }
            ProviderKind::Xai | ProviderKind::OpenAi => {
                // The api crate's `ProviderClient::from_model_with_anthropic_auth`
                // with `None` for the anthropic auth routes via
                // `detect_provider_kind` and builds an
                // `OpenAiCompatClient::from_env` with the matching
                // `OpenAiCompatConfig` (openai / xai / dashscope).
                // That reads the correct API-key env var and BASE_URL
                // override internally, so this one call covers OpenAI,
                // OpenRouter, xAI, DashScope, Ollama, and any other
                // OpenAI-compat endpoint users configure via
                // `OPENAI_BASE_URL` / `XAI_BASE_URL` / `DASHSCOPE_BASE_URL`.
                ApiProviderClient::from_model_with_anthropic_auth(&resolved_model, None)?
            }
        }
    };
    Ok(Self {
        runtime,
        client,
        session_id: session_id.to_string(),
        model,
        enable_tools,
        emit_output,
        allowed_tools,
        tool_registry,
        progress_reporter,
        reasoning_effort: None,
    })
}

